import { cn } from "@/lib/utils"
import { Plus, FlaskConical } from "lucide-react"

type TestCard = {
    title: string
    includes: string
    reportTAT: string
    price: string
}

const items: TestCard[] = [
    {
        title: "Haemogram (CBC)",
        includes: "Includes 26 Tests",
        reportTAT: "Report will be sent within 4 hours",
        price: "Rs. 350",
    },
    {
        title: "Glucose - Fasting",
        includes: "Includes 1 Test",
        reportTAT: "Report will be sent within 3 hours",
        price: "Rs. 85",
    },
    {
        title: "Glucose - Post Prandial",
        includes: "Includes 1 Test",
        reportTAT: "Report will be sent within 3 hours",
        price: "Rs. 85",
    },
]

export default function FrequentlyBooked({ className }: { className?: string }) {
    return (
        <section
            aria-labelledby="freq-tests-heading"
            className={cn(
                "w-full flex justify-center px-2 sm:px-4 py-8",
                className
            )}
            style={{
                background: "linear-gradient(120deg, #eaf5fd 70%, #d4edfa 100%)",
            }}
        >
            <div className={cn("w-full max-w-[1180px]")}>
                <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                    <h2
                        id="freq-tests-heading"
                        className="text-2xl md:text-3xl font-semibold text-[#164e8c] text-center md:text-left"
                    >
                        Frequently Booked Tests
                    </h2>
                </div>
                <div className="mt-7 grid gap-5 xs:grid-cols-1 sm:grid-cols-2 md:grid-cols-3">
                    {items.map((t) => (
                        <div
                            key={t.title}
                            className={cn(
                                "relative h-full rounded-2xl border bg-[#f7fafc] px-5 py-6",
                                "border-[#d0e7ff] shadow-[0_2px_8px_rgba(36,137,209,0.07)] transition hover:shadow-lg"
                            )}
                            tabIndex={0}
                            aria-label={t.title}
                        >
                            <button
                                aria-label={`Add ${t.title}`}
                                className={cn(
                                    "absolute -top-3 -right-3 grid w-9 h-9 place-items-center rounded-full",
                                    "bg-[#2490f7] text-white border border-[#bfe1ff] shadow",
                                    "hover:bg-[#2079c5] focus:bg-[#2079c5] transition"
                                )}
                                tabIndex={-1}
                            >
                                <Plus className="w-5 h-5" />
                            </button>
                            <h3 className="text-[19px] font-semibold text-[#164e8c]">{t.title}</h3>
                            <p className="mt-2 text-[15px] font-medium text-[#4195d0]">{t.includes}</p>
                            <p className="mt-1 text-[15px] text-[#85b0d9]">{t.reportTAT}</p>
                            <div className="mt-4 flex items-end justify-between">
                                <p className="text-[17px] font-semibold text-[#164e8c]">{t.price}</p>
                                <span aria-hidden="true" className="text-[#85b0d9]" title="Lab test icon">
                                    <FlaskConical className="w-7 h-7" />
                                </span>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="mt-10 flex justify-end">
                    <a
                        href="#"
                        className={cn(
                            "inline-flex items-center justify-center rounded-full px-6 py-2.5 text-[15px] font-semibold",
                            "bg-[#2490f7] text-white hover:bg-[#2079c5] focus:bg-[#2079c5] shadow-md transition"
                        )}
                        aria-label="View all tests"
                    >
                        View All
                    </a>
                </div>
            </div>
        </section>
    )
}
